from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from decimal import Decimal
from .models import MerchantExchangeRateSetting

class MerchantExchangeRateOverrideView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def put(self, request, merchant_id, currency_pair):
        override_multiplier = request.data.get("custom_rate")
        # Restrict rate override strictly to merchants owned by authenticated user
        rate_record = MerchantExchangeRateSetting.objects.filter(
            merchant_id=merchant_id,
            merchant__owner=request.user,
            currency_pair=currency_pair
        ).first()
        if not rate_record:
            return Response({"error": "Rate setting not found or unauthorized"}, status=status.HTTP_404_NOT_FOUND)

        rate_record.custom_rate = Decimal(str(override_multiplier))
        rate_record.save(update_fields=["custom_rate"])
        return Response({"status": "Exchange rate overridden", "new_rate": str(rate_record.custom_rate)})
